int a[3][4];   
int (*p)[4];  
//该语句是定义一个数组指针，指向含4个元素的一维数组 
p = a;    
//将该二维数组的首地址赋给p，也就是a[0]或&a[0][0] 
p++;          
//该语句执行过后，也就是p=p+1；p跨过行a[0][]指向了行a[1][]               
//所以数组指针也称指向一维数组的指针，亦称行指针。 
//访问数组中第i行j列的一个元素，有几种操作方式： 
*(p[i]+j)；
*(*(p+i)+j);
(*(p+i))[j];
p[i][j];
//其中，优先级：()>[]>*。

