void resize(size_type new_size) 
{   
    resize(new_size, T()); 
} void resize(size_type new_size, const T& x) 
{  
    if (new_size < size())    
        erase(begin() + new_size, end()); // erase区间范围以外的数据，确保区间以外的数据无效  
    else   insert(end(), new_size - size(), x); // 填补区间范围内空缺的数据，确保区间内的数据有效 
}  
