template <typename T>
class cvector : public NoCopy
{
public:
    typedef viterator<T> iterator; 
    // viterator<T>就是对一个指针的包装，所以完全可以用T*代替viterator <T>         
    typedef const viterator<T> const_iterator;          
    //typedef T* iterator;         
    //typedef const T* const_iterator;         
    cvector() 
    { 
        initData(0); 
    }
    cvector(int capa, const T &val = T())
    {
        initData(capa);
        newCapacity(capacity_);
        for (int i = 0; i < size_; i++)
            buf[i] = val;
    }
    cvector(const_iterator first, const_iterator last)
    {
        initData(last - first);
        newCapacity(capacity_);
        iterator iter = iterator(first);
        int index = 0;
        while (iter != last)
            buf[index++] = *iter++;
    }
    ~cvector()
    {
        if (buf)
        {
            delete[] buf;
            buf = NULL;
        }
        size_ = capacity_ = 0;
    }
    void clear()
    {
        if (buf)
            erase(begin(), end());
    }
    void push_back(const T &t)
    {
        if (size_ == capacity_)
        {
            int capa = calculateCapacity();
            newCapacity(capa);
        }
        buf[size_++] = t;
    }
    void pop_back()
    {
        if (!empty())
            erase(end() - 1);
    }
    int insert(const_iterator iter, const T &t)
    {
        int index = iter - begin();
        if (index <= size_)
        {
            if (size_ == capacity_)
            {
                int capa = calculateCapacity();
                newCapacity(capa);
            }
            memmove(buf + index + 1, buf + index, (size_ - index) * sizeof(T));
            buf[index] = t;
            size_++;
        }
        return index;
    }
    iterator erase(const_iterator iter)
    {
        int index = iter - begin();
        if (index < size_ && size_ > 0)
        {
            memmove(buf + index, buf + index + 1, (size_ - index) * sizeof(T));
            buf[--size_] = T();
        }
        return iterator(iter);
    }
    iterator erase(const_iterator first, const_iterator last)
    {
        iterator first_ = iterator(first);
        iterator last_ = iterator(last);
        while (first_ <= last_--)
            erase(first_);
        return iterator(first_);
    }
    T &front()
    {
        assert(size_ > 0);
        return buf[0];
    }
    T &back()
    {
        assert(size_ > 0);
        return buf[size_ - 1];
    }
    T &at(int index)
    {
        assert(size_ > 0);
        return buf[index];
    }
    T &operator[](int index)
    {
        assert(size_ > 0 && index >= 0 && index < size_);
        return buf[index];
    }
    bool empty() const 
    { 
        return size_ == 0; 
    }
    int size() const
    { 
        return size_; 
    }
    int capacity() const 
    { 
        return capacity_; 
    }
    iterator begin() 
    { 
        return iterator(&buf[0]); 
    }
    iterator end() 
    { 
        return iterator(&buf[size_]); 
    }

private:
    void newCapacity(int capa)
    {
        capacity_ = capa;
        T *newBuf = new T[capacity_];
        if (buf)
        {
            memcpy(newBuf, buf, size_ * sizeof(T));
            delete[] buf;
        }
        buf = newBuf;
    }
    inline int calculateCapacity() 
    { 
        return capacity_ * 3 / 2 + 1; 
    }
    inline void initData(int capa)
    {
        buf = NULL;
        size_ = capacity_ = capa > 0 ? capa : 0;
    }
    int size_;
    int capacity_;
    T *buf;
};
}

