struct Point
{
    Point(int x_ = 0, int y_ = 0) 
    : x(x_)
    , y(y_) 
    {
    }
    int x, y;
};
bool operator<(const Point &p1, const Point &p2)
{
    if (p1.x < p2.x)
    {
        return true;
    }
    else if (p1.x > p2.x)
    {
        return false;
    }
    return p1.y < p2.y;
}
void cvectorTest()
{
    cvector<Point> vect;
    for (int i = 0; i < 10; i++)
    {
        Point p(i, i);
        vect.push_back(p);
    }
    cvector<Point>::iterator iter = vect.begin();
    while (iter != vect.end())
    {
        cout << "[" << iter->x << " " << iter->y << "], ";
        ++iter;
    }
    iter = vect.begin() + 5;
    vect.insert(iter, Point(55, 55));
    iter = vect.end() - 3;
    vect.insert(iter, Point(77, 77));
    cout << endl
        << endl
