bool IsDuplicateNumber(int *array, int n)
{
    if(array==NULL) 
    {
        return false;
    }
    int i,temp;
    for(i=0;i<n;i++)
    {
        while(array[i]!=i)
        {
            if(array[array[i]]==array[i])
            {
                return true;
            }

            temp=array[array[i]];
            array[array[i]]=array[i];
            array[i]=temp;
