        return pHead;
    ListNode *pre=nullptr;
    ListNode *p=pHead;
    ListNode *next=pHead->next;
    while(p)
    {
        p->next=pre;
        pre=p;
        p=next;
        if(next)
        	next=next->next;
    }
    return pre;
